import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String exhibit = scanner.nextLine().replaceAll("\\s+$", "");

        char[] arr = {
            'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm',
            'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z'
        };

        int count = 0;
        int currentIndex = 0;

        for (char ch : exhibit.toCharArray()) {
            int index = -1;
            for (int i = 0; i < arr.length; i++) {
                if (arr[i] == ch) {
                    index = i;
                    break;
                }
            }

            int distanceIndex = Math.abs(index - currentIndex);

            if (distanceIndex > 13) {
                if (index < currentIndex) {
                    count += index + 26 - currentIndex;
                } else {
                    count += currentIndex + 26 - index;
                }
            } else {
                count += distanceIndex;
            }

            currentIndex = index;
        }

        System.out.println(count);
    }
}

